TLM.f("Sancti/08-02",{"officium":"S. Alfonsi Mariæ de Ligorio Episcopi Confessoris et Ecclesiæ Doctoris","rule":["vide C4a","Gloria","CredoDA"],"ruleInherited":["Gloria"],"fallback":"Commune/C4a","sections":{"Introitus":[{"k":"ref","la":"Luc 4:18"},{"k":"text","la":"Spíritus Dómini super me: propter quod unxit me: evangelizáre paupéribus misit me, sanáre contrítos corde."},{"k":"ref","la":"Ps 77:1"},{"k":"text","la":"Atténdite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Spíritus Dómini super me: propter quod unxit me: evangelizáre paupéribus misit me, sanáre contrítos corde."}],"Oratio":[{"k":"text","la":"Deus, qui per beátum Alfónsum Maríam Confessórem tuum atque Pontíficem, animárum zelo succénsum, Ecclésiam tuam nova prole fecundásti: quǽsumus; ut, ejus salutáribus mónitis edócti et exémplis roboráti, ad te perveníre felíciter valeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 2:1-7"},{"k":"text","la":"Caríssime: Confortáre in grátia, quæ est in Christo Jesu: et quæ audísti a me per multos testes, hæc comménda fidélibus homínibus, qui idónei erunt et alios docére. Labóra sicut bonus miles Christi Jesu. Nemo mílitans Deo ímplicat se negótiis sǽculáribus: ut ei pláceat, cui se probávit. Nam et qui certat in agóne, non coronátur, nisi legítime certáverit. Laborántem agrícolam opórtet primum de frúctibus percípere. Intéllege quæ dico: dabit enim tibi Dóminus in ómnibus intelléctum."}],"Graduale":[{"k":"ref","la":"Ps 118:52-53"},{"k":"text","la":"Memor fui judiciórum tuórum a sǽculo, Dómine, et consolátus sum: deféctio ténuit me pro peccatóribus derelinquéntibus legem tuam."},{"k":"ref","la":"Ps 39:11"},{"k":"text","la":"Justítiam tuam non abscóndi in corde meo: veritátem tuam et salutáre tuum dixi. Allelúja, allelúja."},{"k":"ref","la":"Eccles. 49:3-4"},{"k":"text","la":"Ipse est diréctus divínitus in pæniténtiam gentis, et tulit abominatiónes impietátis: et gubernávit ad Dóminum cor ipsíus: et in diébus peccatórum corroborávit pietátem. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 132:1-2"},{"k":"text","la":"Ecce, quam bonum et quam jucúndum, habitáre fratres in unum! Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron. Allelúja."},{"k":"ref","la":"Joann 15:16"},{"k":"text","la":"Pósui vos, ut eátis et fructum afferátis: et fructus vester máneat. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 34:13"},{"k":"text","la":"Ego autem, cum mihi molésti essent, induébar cilício: humiliábam in jejúnio ánimam meam: et orátio mea in sinu meo convertátur."},{"k":"ref","la":"Ps 22:5"},{"k":"text","la":"Parásti in conspéctu meo mensam advérsus eos, qui tríbulant me: impinguásti in óleo caput meum, et calix meus inébrians quam præclárus est!","mark":"V"},{"k":"ref","la":"1 Cor 9:22"},{"k":"text","la":"Factus sum infírmis infírmus, ut infírmos lucrifácerem.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:1-9"},{"k":"text","la":"In illo témpore: Designávit Dóminus et álios septuagínta duos: et misit illos binos ante fáciem suam in omnem civitátem et locum, quo erat ipse ventúrus. Et dicebat illis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam. Ite: ecce, ego mitto vos sicut agnos inter lupos. Nolíte portáre sácculum neque peram neque calceaménta; et néminem per viam salutavéritis. In quamcúmque domum intravéritis, primum dícite: Pax huic dómui: et si ibi fúerit fílius pacis, requiéscet super illum pax vestra: sin autem, ad vos revertátur. In eádem autem domo manéte, edéntes et bibéntes quæ apud illos sunt: dignus est enim operárius mercéde sua. Nolíte transíre de domo in domum. Et in quamcúmque civitátem intravéritis, et suscéperint vos, manducáte quæ apponúntur vobis: et curáte infírmos, qui in illa sunt, et dícite illis: Appropinquávit in vos regnum Dei."}],"Offertorium":[{"k":"rubric","la":"Prov 3:9; 3:27"},{"k":"text","la":"Hónora Dóminum de tua substántia, et de primítiis ómnium frugum tuárum da ei. Noli prohibére benefácere eum, qui potest: si vales, et ipse bénefac."}],"Secreta":[{"k":"text","la":"Cœlésti, Dómine Jesu Christe, sacrifícii igne corda nostra in odórem suavitátis exúre: qui beáto Alfónso Maríæ tribuísti et hæc mystéria celebráre, et per éadem hóstiam tibi sanctam seípsum exhibére:"},{"k":"macro","name":"Qui vivis"}],"Communio":[{"k":"ref","la":"Eccli 50:1; 50:9"},{"k":"text","la":"Sacérdos magnus, qui in vita sua suffúlsit domum, et in diébus suis corroborávit templum, quasi ignis effúlgens et thus ardens in igne."}],"Postcommunio":[{"k":"text","la":"Deus, qui beátum Alfónsum Maríam Confessórem tuum atque Pontíficem fidelem divíni mystérii dispensatórem et præcónem effecísti: ejus méritis precibúsque concéde; ut fidéles tui et frequénter percípiant, et percipiéndo sine fine colláudent."},{"k":"macro","name":"Per Dominum"}]},"hr":{"2d2d711edafcff51":{"t":"Lk 4, 18, Ps 77, 1\n(Lk 4, 18) Duh je Gospodnji na meni. Zato me pomaza. Posla me da naviještam evanđelje siromasima, da liječim klonula srca. (Ps 77, 1) Čuj, puče moj, zakon moj, prigni uho svoje k riječima usta mojih.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Lk 4, 18) Duh je Gospodnji na meni. Zato me pomaza. Posla me da naviještam evanđelje siromasima, da liječim klonula srca.","kn":"(Lk. 4, 18). Duh je Gospodnji na meni, zato me pomaza, da naviještam evanđelje siromasima, da oslobodim potlačene. (Ps. 77, 1) Cuj, puče moj, zakon moj, prikloni uho svoje riječima usta mojih. Slava Ocu... Duh...","knRef":"Kniewald 1942, str. 664–665 (snimka 333) (OCR)"},"effc214659fd6911":{"t":"<i>Pomolimo se</i>.\nBože, koji si po blaženom Alfonsu Mariji priznavaocu i biskupu raspaljenom revnošću za duše obogatio svoju Crkvu novim potomstvom, molimo, da poučeni njegovim spasonosnim opomenama i ojačani primjerom uzmognemo sretno doći k tebe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si po blaženom Alfonsu Mariji, priznavaocu svome i biskupu, raspaljenom revnošću za duše. Crkvu svoju obogatio novom redovničkom družbom, podaj, molimo, da poučeni njegovim spasonosniim opomenama i ohrabreni njegovim primjerom uzmognemo, sretno doći k Tebi, po G. n.","knRef":"Kniewald 1942, str. 664–665 (snimka 333) (OCR)"},"e62f76b82d19344e":{"t":"2 Tim 2, 1-7\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, jačaj se u milosti Isusa Krista! A što si čuo od mene u prisutnosti mnogih svjedoka, predaj vjernim ljudima da se i sami osposobe poučiti i druge. Radi kao dobar vojnik Isusa Krista. Koji služi Bogu ne upliće se u svjetovne poslove da ugodi onome kome se predao. Tako i koji se bori, neće primiti vijenca, ako se ne bori propisno. Kao što treba, poljodjelac koji se trudi najprije će primiti od plodova. Shvati, što govorim! Gospodin će dati da razumiješ sve.","kn":"Čitanje poslariiće bi. Pavla apostola Timoteju (II, 2, 1-7). Predragi! ojačaj se u milosti, koja je u Kristu Isusu. I što sj čuo od mene po mnogim svjedocima, ono predaj vjernim ljudima, koji će biti sposobni i druge naučiti. Podnosi sa mnom na(p,o,re kao dobar vojnik Krista Isusa. Nijedan, koji se bori, ne zapliće se u poslove ovoga života, da ugodi vojvodi. A ako se i tko bori, ne dobije vijenca, ako se pravo :ne bori. Poljodjelac, koji se trudi, najprije treba da primi od plodova. Razumij, što govorim; jer Gospodin dat će ti razum u svemu.","knRef":"Kniewald 1942, str. 664–665 (snimka 333) (OCR)"},"63f8f9ea90912d8a":{"t":"Ps 118, 52-53, Ps 39, 11\n(Ps 118, 52-53) Spominjem se tvojih davnih odredaba, Gospodine, i to me tješi. Obuzima me srdžba radi grješnika koji ostavljaju zakon tvoj. (Ps 39, 11) Ne krijem tvoje odredbe u svom srcu, već naviještam tvoju istinu i spasenje tvoje.\n\nSir 49, 3-4\n<i>Aleluja</i>, <i>aleluja</i>.\nBog ga je poslao da propovijeda narodu pokoru. On je odstranio zloću bezboštva. Njegovo je srce bilo usmjereno prema Gospodinu. U danima kad su grješnici vladali unaprijedio je bogoljubnost. <i>Aleluja</i>.","kn":"(Ps. 118, 52). Opominjem se odredaba Tvojih od iskona, Gospodine, i tješim se. Gnjev me obuzima na bezbožnike, koji ostavljaju zakon Tvoj. Pravde Tvoje ne krijem u srcu svome, istinu Tvoju i spasenje Tvoje kazujem.\n\nAleluja, aleluja. (Crkv. 49, 3, 4). Gospodin ga je odredio da propovijeda narodu pokoru, on je odstranio strahotu bezboštva; upravio je srce svoje Gospodinu i u dane griješnika učvrstio je bogoljubnost, aleluja.","knRef":"Kniewald 1942, str. 664–665 (snimka 333) (OCR)"},"22b5143a1c0cf786":{"t":"Lk 10, 1-9\nSlijedi sveto Evanđelje po Luki. U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu i posla ih dva po dva pred sobom u svaki grad i mjesto kamo je sam kanio doći. I govorio im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte što imaju jer radnik zaslužuje svoju plaću. Ne prelazite iz kuće u kuću. I u kojigod grad uđete i prime vas, jedite, što postave pred vas. I liječite bolesne koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje!","kn":"t Slijedi sv. evanđelje Po Luki (10, 1-9). U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu 1 posla ih dva po dva pred sobom u svaki gnad i mjesto, kamo je sam kanio doći. I govorio, im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve, da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće, i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte, što imaju, jer radnik zaslužuje svoju plaću.. Ne prelazite iz kuće u kuću. I u kojigođ grad uđete 1 prime vas, jedite, što se. donese pred vas. I liječite bolesne, koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje! .","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"142c5b6ff3939b38":{"t":"Izr 3, 9 i 27\nDaj čast Gospodinu od svoga posjeda i prvine svojih plodova. Nemoj priječiti da čini dobro onaj tko može, a i sam čini dobro, ako možeš.","kn":"(Posl. 3, 9, 7). Časti Gospodina od svoga imutka i podaj mu od prvina svih plodova, što ih ubereš. Ne brani, da dobro Sini onaj, koji može, a možeš li:, čini i sam dobro.","knRef":"Kniewald 1942, str. 666–667 (snimka 334) (OCR)"},"8f6a2df64e873c7f":{"t":"Zapali žrtvenim ognjem naša srca na ugodni miris, Gospodine Isuse Kriste, koji si udijelio blaženom Alfonsu Mariji da slavi ove tajne i da po njima prikaže samoga sebe kao svetu žrtvu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Raspali, Gospodine Isuse Kriste, srca: naša nebeskim ognjem, koji si blaženom Alfoinsu Maniji dao da išvetkuje ova otajstva i po njima da sebe samoga Tebi prinese kao svetu žrtvu, koji živiš i kraljuješ ...","knRef":"Kniewald 1942, str. 666–667 (snimka 334) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"3df6986ae282da7f":{"t":"Sir 50, 1 i 9\nEvo velikog svećenika koji je za života svoga podupro kuću i u svoje dane učvrstio hram. Bio je kao žarki oganj i kao tamjan što izgara na ognju.","kn":"(Crkv. 50, 1). Evo velikog svećenika, koji je u dame svoje poduipro Crkvu, sličan je sjajnom plamenu i tamjanu, što izgara u vatri.","knRef":"Kniewald 1942, str. 666–667 (snimka 334) (OCR)"},"6361252714bf9d23":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženog Alfonsa Mariju priznavaoca i biskupa učinio vjernim djeliteljem i glasnikom Božje tajne, daj po njegovu zagovoru i molitvama da je tvoji vjerni često primaju i primajući neprestano slave.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Bože, koj:i si blaženog Alfonisa Mariiju, priznavaoca svoga 1 biB.kupa, učinio vjernim djeliteljem božanske tajne i glasnikom svoje riječi, dopusti, njegovim zaslugama i molitvama, da Tvoji vjerni ova svetotajstva često primaju i primajući bez kraja Tebe hvale, po G. n.","knRef":"Kniewald 1942, str. 666–667 (snimka 334) (OCR)"}}});
